var i=`0378-vol-au-vent`;var n=`world-0378`;var o=`BE`;var s=`western-europe`;var a=4;var l=39;var r={en:`Vol-au-Vent`,ua:`Воловани`};var u={en:`A traditional Belgium dish made with puff pastry shell, chicken thigh, button mushroom, all-purpose flour. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Бельгія. Основні інгредієнти: кошик із листкового тіста, куряче стегно, печериця, пшеничне борошно універсальне. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Roast in a preheated 190°C oven for about 15 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 15 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:15,i:[[`puff-pastry-shell`,8,`pcs`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`chicken-thigh`,430,`g`],[`button-mushroom`,260,`g`],[`unsalted-butter`,50,`g`]]},{en:`Melt the fat, stir in flour and cook gently for about 8 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 8 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:8,i:[[`all-purpose-flour`,55,`g`],[`whole-cow-milk`,350,`ml`],[`chicken-stock`,280,`ml`],[`heavy-cream`,90,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:7,i:[[`parsley`,16,`g`]]}];var d={slug:i,id:n,country:`BE`,region:s,servings:4,minutes:39,title:r,text:u,steps:h};export{o as country,d as default,n as id,l as minutes,s as region,a as servings,i as slug,h as steps,u as text,r as title};